<?php
declare(strict_types=1);
require __DIR__.'/../storage/store.php';
date_default_timezone_set('Asia/Manila');
ini_set('session.use_strict_mode','1');
session_set_cookie_params(['httponly'=>true,'samesite'=>'Lax','secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off']);
session_start();
header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');header('X-Content-Type-Options: nosniff');
$_SESSION['csrf']??=bin2hex(random_bytes(32));
class ApiError extends Exception {public function __construct(string $message,public int $status=422){parent::__construct($message);}}
function fail(string $message,int $code=422):never{throw new ApiError($message,$code);}
function out(array $data):void{echo json_encode(['ok'=>true]+$data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);}
function val(array $d,string $key,int $max=200,bool $required=true):string{if(isset($d[$key])&&!is_string($d[$key]))fail("Invalid $key.");$v=trim($d[$key]??'');if(($required&&$v==='')||strlen($v)>$max)fail("Please enter a valid $key.");return $v;}
function phone(string $v):string{$v=preg_replace('/[\s-]+/','',$v);if(!preg_match('/^(09\d{9}|\+639\d{9})$/D',$v))fail('Enter a valid Philippine mobile number (09XXXXXXXXX or +639XXXXXXXXX).');return $v;}
function email(string $v):string{$v=strtolower($v);if(!filter_var($v,FILTER_VALIDATE_EMAIL))fail('Enter a valid email address.');return $v;}
function contacts(array $d):array{return ['name'=>val($d,'name',120),'phone'=>phone(val($d,'phone',30)),'email'=>email(val($d,'email',160))];}
function choice(array $d,string $key,array $options):string{$v=val($d,$key);if(!in_array($v,$options,true))fail("Invalid $key.");return $v;}
function boundedInt(mixed $v,int $min,int $max,string $label):int{$n=filter_var($v,FILTER_VALIDATE_INT);if($n===false||$n<$min||$n>$max)fail("$label must be between $min and $max.");return $n;}
function nextId(array $rows):int{return $rows?max(array_column($rows,'id'))+1:1;}
function findRow(array $rows,int $id):?array{foreach($rows as $r)if($r['id']===$id)return $r;return null;}
function indexOf(array $rows,int $id):int{foreach($rows as $i=>$r)if($r['id']===$id)return $i;fail('Record not found.',404);}
function currentUser(array $s):?array{$u=findRow($s['users'],(int)($_SESSION['uid']??0));return $u&&$u['active']?$u:null;}
function publicUser(?array $u):?array{if(!$u)return null;unset($u['password_hash']);return $u;}
function requireRole(?array $u,array $roles):void{if(!$u||!in_array($u['role'],$roles,true))fail('You do not have permission for this action.',403);}
function validDate(array $d):string{$date=val($d,'date',10);$dt=DateTimeImmutable::createFromFormat('!Y-m-d',$date);if(!$dt||$dt->format('Y-m-d')!==$date||$date<date('Y-m-d'))fail('Please choose today or a future date.');return $date;}
function schedule(array $d):array{$date=validDate($d);$time=val($d,'time',5);if(!preg_match('/^(?:[01]\d|2[0-3]):(?:00|30)$/D',$time))fail('Please select a valid 30-minute time slot.');$dt=new DateTimeImmutable("$date $time");$end=in_array($dt->format('N'),['6','7'])?'22:00':'21:00';if($time<'07:00'||$time>=$end||$dt<=new DateTimeImmutable())fail('Choose a future time within restaurant operating hours.');return ['date'=>$date,'time'=>$time];}
function items(array $s,mixed $raw,bool $required):array{if(!is_array($raw)||count($raw)>100)fail('Invalid dish selection.');$out=[];$seen=[];foreach($raw as $i){if(!is_array($i))fail('Invalid dish.');$id=boundedInt($i['id']??null,1,PHP_INT_MAX,'Dish');$qty=boundedInt($i['qty']??null,1,20,'Quantity');if(isset($seen[$id]))fail('Duplicate dish selection.');$seen[$id]=true;$dish=findRow($s['menu'],$id);if(!$dish||!$dish['available'])fail('A selected dish is sold out or no longer available.');$out[]=['id'=>$id,'name'=>$dish['name'],'qty'=>$qty,'price'=>$dish['price']];}if($required&&!$out)fail('Please select at least one dish.');return $out;}
function newRecord(array &$s,string $kind,string $prefix,array $data):array{$id=nextId($s[$kind]);$record=['id'=>$id,'ref'=>$prefix.'-'.str_pad((string)$id,5,'0',STR_PAD_LEFT),'created_at'=>date(DATE_ATOM)]+$data;$s[$kind][]=$record;return $record;}
function checkPassword(array $d):string{$p=val($d,'password',72);if(strlen($p)<8)fail('Use at least 8 characters for your password.');return $p;}
function handle(array &$s,string $a,array $d):array{
$u=currentUser($s);$uid=$u['id']??null;
switch($a){
case 'bootstrap':return ['menu'=>$s['menu'],'user'=>publicUser($u),'csrf'=>$_SESSION['csrf']];
case 'register':$c=contacts($d);$password=checkPassword($d);foreach($s['users'] as $r)if($r['email']===$c['email'])fail('An account already uses this email.',409);$id=nextId($s['users']);$s['users'][]=['id'=>$id,'role'=>'Customer','active'=>true,'password_hash'=>password_hash($password,PASSWORD_BCRYPT)]+$c;session_regenerate_id(true);$_SESSION['uid']=$id;return [];
case 'login':$email=email(val($d,'email',160));$password=val($d,'password',72);$attempts=array_filter($_SESSION['attempts']??[],fn($t)=>$t>time()-60);if(count($attempts)>=8)fail('Too many login attempts. Try again in one minute.',429);$_SESSION['attempts']=array_merge($attempts,[time()]);foreach($s['users'] as $r)if($r['email']===$email&&$r['active']&&password_verify($password,$r['password_hash'])){session_regenerate_id(true);$_SESSION['uid']=$r['id'];unset($_SESSION['attempts']);return [];}fail('Email or password is incorrect.',401);
case 'logout':unset($_SESSION['uid']);session_regenerate_id(true);return [];
case 'profile':requireRole($u,['Customer','Staff','Admin']);$c=contacts($d);foreach($s['users'] as $r)if($r['id']!==$uid&&$r['email']===$c['email'])fail('Email already in use.',409);$i=indexOf($s['users'],$uid);$s['users'][$i]=array_replace($u,$c);return [];
case 'order':$c=contacts($d);$slot=schedule($d);$type=choice($d,'type',['Delivery','Pick-Up']);$payment=choice($d,'payment',[$type==='Delivery'?'Cash on Delivery':'Pay on Pickup','GCash','Maya','Credit/Debit Card']);$list=items($s,$d['items']??null,true);$address=[];foreach(['street','barangay','city','landmark'] as $key)$address[$key]=$type==='Delivery'?val($d,$key,200,$key!=='landmark'):'';$subtotal=round(array_sum(array_map(fn($i)=>$i['price']*$i['qty'],$list)),2);$fee=$type==='Delivery'?50:0;$online=in_array($payment,['GCash','Maya','Credit/Debit Card']);$r=newRecord($s,'orders','ORD',$c+$slot+$address+['user_id'=>$uid,'type'=>$type,'items'=>$list,'notes'=>val($d,'notes',1000,false),'subtotal'=>$subtotal,'fee'=>$fee,'total'=>$subtotal+$fee,'payment'=>$payment,'payment_status'=>$online?'Pending':'Unpaid','status'=>$online?'Pending Payment':'Pending']);return ['ref'=>$r['ref'],'status'=>$r['status'],'total'=>$r['total']];
case 'reservation':$c=contacts($d);$slot=schedule($d);$guests=boundedInt($d['guests']??null,1,200,'Guests');$r=newRecord($s,'reservations','RES',$c+$slot+['user_id'=>$uid,'guests'=>$guests,'large_group'=>$guests>=10,'occasion'=>choice($d,'occasion',['Birthday','Family Reunion','Anniversary','Business Meeting','Others']),'seating'=>choice($d,'seating',['Regular table','Group table','No preference']),'preorder'=>items($s,$d['preorder']??[],false),'notes'=>val($d,'notes',1000,false),'status'=>'Pending']);return ['ref'=>$r['ref'],'status'=>$r['status']];
case 'inquiry':$c=contacts($d);$r=newRecord($s,'inquiries','CAT',$c+['user_id'=>$uid,'date'=>validDate($d),'event'=>choice($d,'event',['Birthday','Family Reunion','Anniversary','Corporate Event','Others']),'guests'=>boundedInt($d['guests']??null,1,10000,'Guests'),'venue'=>val($d,'venue',250),'package'=>choice($d,'package',['Party tray – small (inquire)','Party tray – large (inquire)','Full catering (inquire)','Custom package / unsure']),'notes'=>val($d,'notes',1000,false),'status'=>'Pending']);return ['ref'=>$r['ref'],'status'=>$r['status']];
case 'history':requireRole($u,['Customer','Staff','Admin']);$result=[];foreach(['orders','reservations','inquiries'] as $k)$result[$k]=array_values(array_filter($s[$k],fn($r)=>$r['user_id']===$uid));return $result;
case 'dashboard':requireRole($u,['Staff','Admin']);$result=array_intersect_key($s,array_flip(['orders','reservations','inquiries','menu']));if($u['role']==='Admin')$result['users']=array_map('publicUser',$s['users']);return $result;
case 'update_record':requireRole($u,['Staff','Admin']);$kind=choice($d,'kind',['orders','reservations','inquiries']);$idx=indexOf($s[$kind],boundedInt($d['id']??null,1,PHP_INT_MAX,'Record'));$r=&$s[$kind][$idx];$allowed=match($kind){'orders'=>['Pending','Pending Payment','Confirmed','Preparing','Ready','Out for Delivery','Completed','Cancelled'],'reservations'=>['Pending','Confirmed','Completed','Cancelled','No-Show'],'inquiries'=>['Pending','Under Review','Quoted','Completed','Cancelled']};$status=choice($d,'status',$allowed);if($kind==='reservations'&&$status!==$r['status']){$trans=['Pending'=>['Confirmed','Cancelled'],'Confirmed'=>['Completed','Cancelled','No-Show']];if(!in_array($status,$trans[$r['status']]??[],true))fail('Invalid reservation status transition. Confirm a pending reservation before marking it completed or no-show.');}if($kind==='orders'){$pay=choice($d,'payment_status',['Unpaid','Pending','Paid','Failed','Refunded']);$online=in_array($r['payment'],['GCash','Maya','Credit/Debit Card']);if($online&&$pay!==$r['payment_status'])fail('Online payment can only be updated by a verified payment gateway; it is not connected in this demo.');if($online&&$pay!=='Paid'&&!in_array($status,['Pending Payment','Cancelled'],true))fail('Online payment must be verified before confirming this order.');if(!$online&&!in_array($pay,['Unpaid','Paid'],true))fail('Cash payments may be recorded as Paid or Unpaid.');$r['payment_status']=$pay;} $r['status']=$status;return [];
case 'save_menu':requireRole($u,['Staff','Admin']);$id=boundedInt($d['id']??null,0,PHP_INT_MAX,'Dish');if(!is_bool($d['available']??null))fail('Invalid availability.');if($u['role']==='Staff'){if(!$id)fail('Only Admin can add dishes.',403);$i=indexOf($s['menu'],$id);$s['menu'][$i]['available']=$d['available'];return [];} $price=filter_var($d['price']??null,FILTER_VALIDATE_FLOAT);if($price===false||$price<1||$price>100000)fail('Enter a valid price.');$img=val($d,'image',500,false);if($img&&!preg_match('~^(assets/[A-Za-z0-9_.-]+|https://[^\s]+)$~D',$img))fail('Use a local assets path or HTTPS image URL.');$dish=['id'=>$id?:nextId($s['menu']),'name'=>val($d,'name',120),'category'=>choice($d,'category',['Soups','Grilled Dishes','Main Dishes','Noodles','Rice, Desserts & Drinks']),'description'=>val($d,'description',500),'price'=>round($price,2),'tag'=>val($d,'tag',50,false),'serving'=>val($d,'serving',100,false),'dietary'=>val($d,'dietary',200,false),'image'=>$img,'available'=>$d['available']];if($id)$s['menu'][indexOf($s['menu'],$id)]=$dish;else $s['menu'][]=$dish;return [];
case 'update_user':requireRole($u,['Admin']);$id=boundedInt($d['id']??null,1,PHP_INT_MAX,'User');if($id===$uid)fail('You cannot modify your own access.');$i=indexOf($s['users'],$id);$role=choice($d,'role',['Customer','Staff','Admin']);if(!is_bool($d['active']??null))fail('Invalid account status.');$s['users'][$i]['role']=$role;$s['users'][$i]['active']=$d['active'];return [];
default:fail('Unknown action.',404);
}}
try{$action=$_GET['action']??'';if(!is_string($action))fail('Invalid action.');$method=$_SERVER['REQUEST_METHOD'];$reads=['bootstrap','history','dashboard'];if(in_array($action,$reads,true)){if($method!=='GET')fail('Method not allowed.',405);$data=[];}else{if($method!=='POST')fail('Method not allowed.',405);if(!hash_equals($_SESSION['csrf'],$_SERVER['HTTP_X_CSRF_TOKEN']??''))fail('Session expired. Refresh the page and try again.',403);$raw=file_get_contents('php://input',false,null,0,65537);if(strlen($raw)>65536)fail('Request too large.',413);$data=json_decode($raw,true);if(!is_array($data))fail('Invalid request.');}out(withStore(fn(&$state)=>handle($state,$action,$data),!in_array($action,$reads,true)));}catch(ApiError $e){http_response_code($e->status);echo json_encode(['ok'=>false,'error'=>$e->getMessage()]);}catch(Throwable $e){error_log((string)$e);http_response_code(500);echo json_encode(['ok'=>false,'error'=>'Server storage is unavailable. Check the project setup.']);}
